(()=>{
const checked='9 Sep 2026';
const countryCodes={'Algeria':'DZ','Angola':'AO','Benin':'BJ','Botswana':'BW','Burkina Faso':'BF','Burundi':'BI','Cabo Verde':'CV','Cameroon':'CM','Central African Republic':'CF','Chad':'TD','Comoros':'KM','Congo, Democratic Republic':'CD','Congo, Republic':'CG','Côte d’Ivoire':'CI','Djibouti':'DJ','Egypt':'EG','Equatorial Guinea':'GQ','Eritrea':'ER','Eswatini':'SZ','Ethiopia':'ET','Gabon':'GA','Gambia':'GM','Ghana':'GH','Guinea':'GN','Guinea-Bissau':'GW','Kenya':'KE','Lesotho':'LS','Liberia':'LR','Libya':'LY','Madagascar':'MG','Malawi':'MW','Mali':'ML','Mauritania':'MR','Mauritius':'MU','Morocco':'MA','Mozambique':'MZ','Namibia':'NA','Niger':'NE','Nigeria':'NG','Rwanda':'RW','São Tomé and Príncipe':'ST','Senegal':'SN','Seychelles':'SC','Sierra Leone':'SL','Somalia':'SO','South Africa':'ZA','South Sudan':'SS','Sudan':'SD','Tanzania':'TZ','Togo':'TG','Tunisia':'TN','Uganda':'UG','Zambia':'ZM','Zimbabwe':'ZW'};
const profiles={
 'Botswana':{code:'BW',status:'Expanded field profile',gateways:['Maun','Kasane','Gaborone'],landscapes:['Okavango wetlands','Chobe–Linyanti river systems','Kalahari grasslands and salt pans'],season:'May to October is broadly drier and cooler; wildlife often gathers around permanent water. November to April generally brings heat, rain, migrant birds and greener landscapes. Okavango flood timing is distinct from local rainfall and varies by year.',regions:[['Okavango & Moremi','Permanent channels, seasonal floodplains, islands and woodland across the Delta and Moremi landscape.'],['Chobe, Savuti & Linyanti','River frontage, dry woodland and major wildlife corridors in northern Botswana.'],['Makgadikgadi & Nxai Pan','Salt-pan horizons, grasslands, seasonal water and desert-adapted wildlife.'],['Central Kalahari & Khutse','Remote semi-arid landscapes, fossil valleys and wide seasonal grasslands.'],['Northern Tuli','Limpopo and Shashe river country, rocky kopjes and private or community conservation areas.'],['Tsodilo & the Panhandle','Rock-art heritage and the upper Okavango’s deeper channels and riparian habitats.']],sources:[['Botswana Tourism Organisation','https://www.botswanatourism.co.bw/explore'],['Ministry of Environment and Tourism','https://www.gov.bw/ministries/ministry-environment-and-tourism']]},
 'South Africa':{code:'ZA',status:'Expanded field profile',gateways:['Johannesburg','Cape Town','Durban','Mbombela and Hoedspruit'],landscapes:['Lowveld savanna','Kalahari and Karoo','Cape mountains, fynbos and coast'],season:'Safari conditions vary greatly by biome. The northeast is usually drier in the austral winter and wetter in summer; the southwestern Cape follows a different winter-rainfall pattern. Check the specific park before travel.',regions:[['Kruger & the Lowveld','Large connected savanna landscapes, river systems and public and private reserves.'],['Kgalagadi','Arid Kalahari dunes, dry riverbeds and desert-adapted wildlife.'],['Mapungubwe','Limpopo–Shashe landscapes combining biodiversity, archaeology and cultural heritage.'],['Addo & the Eastern Cape','Thicket, open country and conservation areas spanning inland habitats toward the coast.'],['KwaZulu-Natal reserves & wetlands','Savanna, estuaries, coastal forest and marine environments.'],['Cape, Karoo & Garden Route','Fynbos, mountains, semi-desert, forests and coast rather than one conventional safari biome.']],sources:[['South African National Parks','https://www.sanparks.org/'],['South African Tourism','https://www.southafrica.net/']]},
 'Namibia':{code:'NA',status:'Expanded field profile',gateways:['Windhoek','Walvis Bay'],landscapes:['Etosha salt-pan system','Namib Desert and Atlantic coast','Escarpment, rugged northwest and Zambezi wetlands'],season:'The cooler dry period commonly falls from May to October, while the main rains generally occur during the hotter summer. Wildlife, road and water conditions differ sharply between desert, plateau and the Zambezi region.',regions:[['Etosha','A vast pan system with surrounding waterholes, woodland and grassland.'],['Namib-Naukluft & Sossusvlei','Ancient desert, high dunes, gravel plains and mountain canyons.'],['Skeleton Coast','Fog-influenced Atlantic desert, dune fields and highly remote coast.'],['Kunene & the northwest','Rugged escarpment and desert valleys supporting dispersed, mobile wildlife.'],['Zambezi conservation landscape','Rivers, floodplains and woodlands connecting wider transboundary ecosystems.'],['Waterberg & the south','Sandstone plateau habitat plus southern desert, canyon and succulent landscapes.']],sources:[['Namibia Wildlife Resorts parks','https://www.nwr.com.na/national-parks/'],['Ministry of Environment, Forestry and Tourism','https://www.meft.gov.na/']]},
 'Zimbabwe':{code:'ZW',status:'Expanded field profile',gateways:['Harare','Victoria Falls','Bulawayo'],landscapes:['Zambezi valley and floodplain','Mopane and teak woodland','Granite hills and eastern mountains'],season:'The cooler dry season commonly runs from about May to October and the warmer rains from roughly November to April. Heat, water levels and access can vary considerably by park and year.',regions:[['Hwange','Extensive woodland and grassland with natural and managed water sources.'],['Mana Pools & the middle Zambezi','River terraces, floodplain, woodland and escarpment wilderness.'],['Gonarezhou','Large lowveld landscape of rivers, sandstone cliffs and mopane woodland.'],['Matobo','Granite kopjes, cultural landscapes and important wildlife areas.'],['Victoria Falls & Zambezi parks','Riverine habitats around a globally significant waterfall landscape.'],['Eastern Highlands','Montane scenery, forest, grassland and high-rainfall biodiversity.']],sources:[['Zimbabwe Parks and Wildlife Management Authority','https://www.zimparks.org.zw/'],['Zimbabwe Tourism Authority','https://zimbabwetourism.net/']]},
 'Zambia':{code:'ZM',status:'Expanded field profile',gateways:['Lusaka','Livingstone','Mfuwe'],landscapes:['Luangwa Valley','Kafue basin and floodplains','Zambezi river systems and Bangweulu wetlands'],season:'The broad dry season usually falls from May to October and the rains from November to April. Access, camp operations, river levels and wildlife movement are strongly local and must be checked for the intended area.',regions:[['South & North Luangwa','River, lagoon, floodplain and woodland ecosystems along the Luangwa Valley.'],['Lower Zambezi','Escarpment-to-river habitat facing a wider transboundary conservation landscape.'],['Kafue','A very large and varied system including woodland, rivers and seasonal floodplains.'],['Liuwa Plain','Open grassland and seasonal wetlands in western Zambia.'],['Bangweulu','A major wetland and floodplain landscape with distinctive water-dependent wildlife.'],['Mosi-oa-Tunya & the upper Zambezi','Riverine wildlife and the Zambian side of the Victoria Falls landscape.']],sources:[['Department of National Parks and Wildlife','https://www.mot.gov.zm/dnpw/'],['Zambia Tourism','https://www.zambiatourism.com/']]},
 'Kenya':{code:'KE',status:'Expanded field profile',gateways:['Nairobi','Mombasa','Nanyuki'],landscapes:['Mara–Serengeti grasslands','Rift Valley lakes and escarpments','Northern rangelands, highlands and Indian Ocean coast'],season:'Kenya spans equatorial coast, highlands and dry northern country, so one national season cannot predict a trip. Many safari areas experience broadly drier periods around January to February and June to October, with rains often concentrated around March to May and again later in the year.',regions:[['Maasai Mara ecosystem','Open grasslands, river corridors and conservancy landscapes connected to the wider Serengeti system.'],['Amboseli & Chyulu','Wetlands, plains and volcanic foothills within a cross-border Kilimanjaro landscape.'],['Tsavo East & West','A vast southeastern ecosystem of semi-arid plains, lava country, springs and river habitats.'],['Laikipia & the central highlands','Plateau, ranch and community conservancy landscapes below Mount Kenya.'],['Samburu, Buffalo Springs & Shaba','Northern riverine woodland and arid country shaped by the Ewaso Ng’iro.'],['Rift lakes, forests & marine parks','Freshwater and alkaline lakes, montane forests, coral reefs and coastal habitats.']],sources:[['Kenya Wildlife Service','https://kws.go.ke/parks/'],['Magical Kenya','https://magicalkenya.com/']]},
 'Tanzania':{code:'TZ',status:'Expanded field profile',gateways:['Arusha and Kilimanjaro','Dar es Salaam','Zanzibar','Mwanza'],landscapes:['Serengeti plains and volcanic highlands','Miombo woodland and great rivers','Eastern Arc forests, Rift lakes and Indian Ocean coast'],season:'Northern and coastal rainfall patterns differ from parts of the south and west. June to October is broadly drier in many safari regions; rainfall often occurs from November onward with a more sustained wet period around March to May. Migration timing and river crossings are natural events, never guarantees.',regions:[['Serengeti & Ngorongoro landscape','Grassland, woodland and volcanic highlands forming part of a wider transboundary ecosystem.'],['Tarangire, Manyara & Arusha','Rift escarpment, lakes, river valleys, woodland and highland habitats.'],['Nyerere & Mikumi','Large southern river, wetland, woodland and floodplain systems.'],['Ruaha','A major central landscape where eastern and southern African ecological influences meet.'],['Katavi & western Tanzania','Remote floodplains, woodland, lakes and escarpment environments.'],['Gombe, Mahale, mountains & coast','Lake Tanganyika forests, montane biodiversity, marine environments and island nature.']],sources:[['Tanzania National Parks','https://www.tanzaniaparks.go.tz/nationalparks'],['Tanzania Tourism','https://www.tanzaniatourism.go.tz/']]},
 'Uganda':{code:'UG',status:'Expanded field profile',gateways:['Entebbe and Kampala','Kasese','Kisoro'],landscapes:['Albertine Rift forests and mountains','Nile river, lakes and savanna','Volcanic highlands and northeastern dry country'],season:'Uganda is equatorial but altitude strongly shapes local climate. Drier windows are often experienced around December to February and June to August, while rainfall can occur at any time—especially in forests and mountains. Trail and road conditions require local confirmation.',regions:[['Bwindi & Mgahinga','Southwestern montane and bamboo forests within the wider Albertine Rift and Virunga landscapes.'],['Queen Elizabeth & Kyambura','Savanna, crater lakes, wetlands and forested gorges between the Rwenzori and Lake Edward.'],['Murchison Falls','Nile gorge, riverine habitats, woodland and broad northern savanna.'],['Kibale & Semuliki','Primate-rich forest, wetlands and lowland forest at the Rift’s western edge.'],['Kidepo Valley','Remote northeastern savanna, mountains and seasonal river valleys.'],['Lake Mburo, Rwenzori & Mount Elgon','Wooded savanna plus high-altitude trekking and montane ecosystems.']],sources:[['Uganda Wildlife Authority','https://ugandawildlife.org/national-parks/'],['Explore Uganda','https://www.exploreuganda.com/']]},
 'Rwanda':{code:'RW',status:'Expanded field profile',gateways:['Kigali','Musanze','Rusizi'],landscapes:['Virunga volcanoes and montane forest','Albertine Rift rainforest','Eastern savanna, wetlands and lakes'],season:'Rwanda’s elevation moderates its equatorial climate. Drier periods are generally associated with June to September and around December to February, but rain remains possible and mountain conditions change quickly.',regions:[['Volcanoes','Virunga slopes with bamboo, evergreen forest, heath and high-altitude environments.'],['Nyungwe','Large southwestern montane rainforest with ridges, wetlands and diverse primate habitat.'],['Akagera','Lower-elevation eastern savanna, woodland, wetland and lake systems.'],['Gishwati–Mukura','Two montane forest areas on the Congo–Nile divide.'],['Lake Kivu & Congo Nile ridge','Freshwater shoreline and steep western highlands linking forest and community landscapes.'],['Kigali & cultural circuit','The practical national gateway for museums, memorials and onward journeys.']],sources:[['Visit Rwanda national parks','https://visitrwanda.com/tourism/destinations/national-parks/'],['Rwanda Development Board','https://rdb.rw/']]},
 'Ethiopia':{code:'ET',status:'Expanded field profile',gateways:['Addis Ababa','Bahir Dar','Gondar','Hawassa'],landscapes:['Afro-alpine highlands','Rift Valley lakes and savanna','Lowland drylands, escarpments and forests'],season:'Ethiopia’s altitude range produces sharply different local climates. Much of the northern and central highlands is broadly drier from October into early spring, while rainfall patterns differ in southern and eastern regions. Road, trail and security conditions must be checked immediately before travel.',regions:[['Bale Mountains','Afro-alpine plateau, volcanic peaks, wetlands and the Harenna Forest.'],['Simien Mountains','Deep escarpments, high plateaus and distinctive highland wildlife habitats.'],['Rift Valley lakes','A chain of freshwater and alkaline lakes, wetlands, woodland and bird habitats.'],['Awash & the Afar transition','Rift Valley savanna, riverine habitat, volcanic terrain and dry lowlands.'],['Omo, Mago & Nech Sar landscapes','Southern lakes, savanna, forest and culturally important living landscapes.'],['Gambella & western forests','Lowland rivers, wetlands, grasslands and forest systems toward the South Sudan border.']],sources:[['Ethiopian Wildlife Conservation Authority','https://ewca.gov.et/'],['Visit Ethiopia','https://visitethiopia.et/']]}
};
const esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function placeContext(name){const value=name.toLowerCase();if(/national park|game reserve|nature reserve|wildlife reserve|sanctuary/.test(value))return'Protected-area starting point in the Pocketbook index. Confirm boundaries, access, permits and operating conditions with the responsible authority.';if(/lake|delta|river|falls|wetland|pan|coast|marine|archipelago|island|beach|oasis/.test(value))return'Water, wetland, island or coastal landscape in the Pocketbook index. Conditions, access and activities vary seasonally and locally.';if(/mount|mountain|highland|escarpment|peak|plateau|massif|gorge|valley/.test(value))return'Highland, geological or scenic landscape in the Pocketbook index. Confirm routes, weather, access and guide requirements locally.';if(/desert|dune|sahara|kalahari|karoo|ténéré|chott/.test(value))return'Arid-land landscape in the Pocketbook index. Heat, water, distance and road preparation require current local planning.';return'Curated nature, heritage or landscape starting point. Confirm current access and visitor arrangements locally.'}
function fallback(country,atlasRow){const highlights=String(atlasRow?.[2]||'').split(/,|·|—/).map(x=>x.trim()).filter(Boolean).slice(0,8),code=countryCodes[country]||'';return {code,gateways:[],landscapes:[],regions:highlights.map(name=>[name,placeContext(name)]),sources:code?[['Protected Planet country profile',`https://www.protectedplanet.net/country/${code}`],['GBIF country biodiversity activity',`https://www.gbif.org/country/${code}/summary`]]:[]}}
window.countryDepthHtml=(country,atlasRow)=>{const p=profiles[country]||fallback(country,atlasRow);return `<section class="entry-section country-depth" data-depth-country="${esc(country)}" data-depth-code="${esc(p.code)}"><div class="depth-heading"><div><div class="entry-kicker">FIELD PROFILE</div><h3>Safari regions at a glance</h3></div></div><nav class="country-shortcuts" aria-label="${esc(country)} pocketbook tools">${p.code?`<button type="button" data-country-wildlife="${esc(p.code)}">Wildlife</button>`:''}<button type="button" data-country-map="${esc(country)}">Map</button><button type="button" data-country-language>Languages</button><button type="button" data-country-safety="${esc(country)}">Safety</button></nav>${p.gateways.length?`<div class="depth-group"><strong>Common journey gateways</strong><p>${p.gateways.map(esc).join(' · ')}</p></div>`:''}${p.landscapes.length?`<div class="depth-group"><strong>Landscape compass</strong><div class="landscape-chips">${p.landscapes.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div>`:''}<div class="region-list">${p.regions.map(([name,note])=>`<article><h4>${esc(name)}</h4><p>${esc(note)}</p></article>`).join('')}</div>${p.season?`<div class="season-note"><strong>Seasonal pattern—not a forecast</strong><p>${esc(p.season)}</p><small>Conditions vary by year and location. Confirm roads, weather, water, access and opening status before setting out.</small></div>`:''}<div class="depth-sources"><strong>Reference starting points</strong>${p.sources.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener">${esc(name)} ↗</a>`).join('')}<small>Bundled editorial profile reviewed ${checked}. It is not live operational advice.</small></div></section>`};
window.mountCountryDepth=(country)=>{const root=[...document.querySelectorAll('.country-depth')].find(node=>node.dataset.depthCountry===country);if(!root)return;root.querySelector('[data-country-language]')?.addEventListener('click',()=>root.nextElementSibling?.scrollIntoView({behavior:'smooth',block:'start'}));root.querySelector('[data-country-wildlife]')?.addEventListener('click',event=>{const code=event.currentTarget.dataset.countryWildlife;if(!code)return;document.querySelector('.country-close')?.click();window.openPocketbookView?.('field');document.querySelector('#faunaMode [data-mode="database"]')?.click();const select=document.getElementById('faunaCountry');if(select){select.value=code;select.dispatchEvent(new Event('change',{bubbles:true}))}});root.querySelector('[data-country-map]')?.addEventListener('click',event=>{document.querySelector('.country-close')?.click();window.openPocketbookView?.('map');const input=document.getElementById('mapSearch');if(input){input.value=event.currentTarget.dataset.countryMap;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus()}});root.querySelector('[data-country-safety]')?.addEventListener('click',event=>{document.querySelector('.country-close')?.click();document.getElementById('sosButton')?.click();const select=document.getElementById('safetyCountry');if(select){select.value=event.currentTarget.dataset.countrySafety;select.dispatchEvent(new Event('change',{bubbles:true}))}})};
})();
